def control(obs):
    global ph, d
    if 'ph' not in globals():
        ph = 'rev'
        d = 0.0
    st = obs['status']
    hold = obs['motion']['hold_s']
    if st in ('PINNED', 'JACKKNIFED') and ph != 'fwd':
        ph = 'fwd'
        d = 0.0
    if ph == 'fwd':
        if hold > 0:
            return (0.0, 0.0, 0)
        d += obs['motion']['v_mps'] * obs['dt']
        if d < 1.2:
            return (0.0, 0.4, 0)
        ph = 'rev'
    y = obs['rig']['trailer_rear'][1]
    h = obs['hitch_deg']
    e = y + 0.3
    hd = max(-6.0, min(6.0, -5.0 * e))
    steer = max(-20.0, min(20.0, 3.0 * (h - hd)))
    return (steer, -0.4, -23)

